/* eslint-disable no-invalid-this */

'use strict';

// MODULES //

var spec2svg = require( '@stdlib/plot/vega/base/spec2svg' );


// MAIN //

/**
* Generates a Vega specification.
*
* @private
* @param {Callback} clbk - callback to invoke with rendered visualization
* @returns {void}
*/
function render( clbk ) {
	spec2svg( this.toJSON(), clbk );
}


// EXPORTS //

module.exports = render;
